TERMS=[('Slip angle','The angle between the direction a tire points and the direction its contact patch travels.'),('Slip ratio','A measure of the difference between circumferential tire speed and road speed during driving or braking.'),('Tire load sensitivity','The tendency for tire force capacity to increase less than proportionally as vertical load increases.'),('Friction circle / ellipse','A simplified picture of how a tire shares its available force between braking, driving, and cornering.'),('Lateral load transfer','The change in left/right tire loads associated with cornering.'),('Longitudinal load transfer','The change in front/rear tire loads associated with braking or acceleration.'),('Roll center','A geometric reference used to describe suspension force transmission and body roll.'),('Roll couple','The rolling moment associated with lateral forces and their lever arms.'),('Wheel rate','The effective spring stiffness measured at the wheel.'),('Motion ratio','The relationship between wheel movement and spring or damper movement; always state the convention.'),('Ride rate','The effective vertical stiffness seen by the sprung mass, including relevant compliances such as the tire.'),('Natural frequency','The frequency at which a system tends to oscillate when disturbed.'),('Critical damping','The damping level separating oscillatory from non-oscillatory response in an ideal second-order system.'),('Aero balance','The front/rear distribution of aerodynamic load.'),('Center of pressure','The point through which the resultant aerodynamic force is represented as acting.'),('Understeer gradient','A measure of how required steering changes with lateral acceleration under specified steady-state conditions.'),('Differential locking','Resistance to a speed difference between the driven wheels.'),('Crossweight','The share of total static vehicle weight carried by a specified diagonal pair.'),('Stagger','The difference between outside and inside tire rolling circumferences.'),('Bump steer','A change in wheel steer angle as the suspension moves.'),('Anti-dive','Suspension geometry that reacts part of the braking pitch moment through suspension forces.'),('Anti-squat','Suspension geometry that reacts part of the acceleration pitch moment through suspension forces.')]

def render_dynamics():
 out='<div class="note"><strong>How to use this guide</strong>These are generalized first-order tendencies, not universal rules. Results depend on the vehicle, tire, track, aero map, geometry, driver inputs, and other setup parameters. Change one clearly defined thing, record conditions, and compare driver feedback with measurements.</div>'
 out+='<nav class="topic-nav" aria-label="Vehicle dynamics topics">'+''.join(f'<a href="#{id}">{title.split(":")[0]}</a>' for id,title,rows in GROUPS)+'</nav>'
 for id,title,rows in GROUPS:
  out+=f'<details id="{id}" class="dynamics-section"><summary><h2>{title}</h2><span class="expand-label" aria-hidden="true"></span></summary><div class="dynamics-body">'
  if id=='dampers':
   out+='''<p class="section-intro">Dampers primarily shape transient motion and the timing of load transfer. They do not simply change the total acceleration-driven load transfer.</p><div class="card cream"><h3>Damper shaft-velocity guide</h3><p>“Low speed” and “high speed” describe how fast the damper shaft moves, not how fast the car travels. The dividing point depends on the damper and its valving.</p><div class="role-list"><div class="role-item"><h4>Low shaft velocity</h4><p>Often associated with roll, pitch, heave, brake application/release, and steering transitions.</p></div><div class="role-item"><h4>High shaft velocity</h4><p>Often associated with curbs, sharp bumps, surface impacts, and sudden wheel movement.</p></div></div><p><strong>Compression:</strong> the damper shortens. <strong>Rebound:</strong> the damper extends. Adjuster ranges can overlap, so use the damper’s force–velocity curves and documentation.</p></div>'''
  if id=='oval':out+='<p class="section-intro">Oval / generalized. Conventions and direction of travel matter. <strong>Wedge</strong> commonly refers to crossweight or an adjustment to it. <strong>Rounds</strong> are turns of a spring perch or jack bolt used to change the setup. They can change wedge and ride height, but rounds and wedge are not the same measurement.</p><div class="equation">Crossweight % = (RF + LR) / total vehicle weight × 100<br>Stagger = outside tire circumference − inside tire circumference</div>'
  if id=='tires':out+='<p class="section-intro">Think in terms of an operating window, not “higher pressure = less grip.”</p>'
  for name,effect,where,why,opposite,conditions in rows:
   out+=f'<article class="adjustment"><h3>{e(name)}</h3><dl>'+''.join(f'<dt>{label}</dt><dd>{e(text)}</dd>' for label,text in [('Typical effect',effect),('Where it matters',where),('Why',why),('Opposite adjustment',opposite),('Conditions',conditions)])+'</dl></article>'
  out+='</div></details>'
 out+='<details class="dynamics-section"><summary><h2>Terms to learn next</h2><span class="expand-label" aria-hidden="true"></span></summary><div class="dynamics-body"><dl class="terms" style="margin-top:25px">'+''.join(f'<div><dt>{e(t)}</dt><dd>{e(d)}</dd></div>' for t,d in TERMS)+'</dl></div></details>'
 out+='''<aside class="source-links"><h3>Go deeper with technical references</h3><p class="muted">Use established texts and manufacturer documentation alongside this introductory guide.</p><ul><li><a href="https://www.millikenresearch.com/rcvd.html" target="_blank" rel="noopener noreferrer">Milliken &amp; Milliken — Race Car Vehicle Dynamics</a></li><li><a href="books.html">Carroll Smith — Tune to Win, and the full reading list</a></li><li><a href="https://optimumg.com/technical-papers/" target="_blank" rel="noopener noreferrer">OptimumG technical papers</a></li><li><a href="https://www.penskeshocks.com/resources/downloads" target="_blank" rel="noopener noreferrer">Penske Racing Shocks manuals and tuning guides</a></li><li><a href="https://apracing.com/race-car/brake-discs/disc-temperatures" target="_blank" rel="noopener noreferrer">AP Racing — disc temperatures</a></li><li><a href="https://apracing.com/race-car/brake-discs/disc-cooling" target="_blank" rel="noopener noreferrer">AP Racing — disc cooling</a></li></ul></aside>'''
 return out
